// Variants of the reference export: quarterly, negative costs, pro-rata funding, no net line, nominal IRR, text dates. Each with its ground truth.
const X=require('../package/dist/xlsx.full.min.js'),fs=require('fs');
function irrP(fl){const f=r=>fl.reduce((s,c,t)=>s+c/Math.pow(1+r,t),0);let lo=-0.99,hi=1,flo=f(lo);if(flo*f(hi)>0)return NaN;for(let i=0;i<300;i++){const m=(lo+hi)/2,fm=f(m);if(flo*fm<=0)hi=m;else{lo=m;flo=fm}}return(lo+hi)/2}
function build(V,ch={}){const ppy=V.q?4:12,T=V.q?20:60,z=()=>Array(T).fill(0),L={land:z(),cons:z(),fees:z(),cont:z(),dep:z(),settle:z(),sell:z()};
  const P={land:90e6,cons:420e6,gdv:760e6,rate:8,equity:180e6,ltc:0.6};const price=P.gdv*(1+(ch.price||0)/100),cons=P.cons*(1+(ch.cost||0)/100),land=P.land*(1+(ch.land||0)/100),dl=Math.round((ch.delay||0)*ppy/12),rate=(P.rate+(ch.rate||0))/100/ppy;
  const cs=V.q?1:3,cm=V.q?10:28;L.land[0]=land;const w=[];for(let m=0;m<cm;m++)w.push(Math.sin(Math.PI*(m+0.5)/cm));const sw=w.reduce((a,b)=>a+b,0);for(let m=0;m<cm;m++){const v=cons*w[m]/sw;L.cons[cs+m]=v;L.fees[cs+m]=v*0.1;L.cont[cs+m]=v*0.05}
  const dm=V.q?4:12,d0=V.q?2:6;for(let m=0;m<dm;m++)L.dep[d0+m+dl]+=price*0.1/dm;const done=cs+cm,sm=V.q?2:6;for(let m=0;m<sm;m++)L.settle[done+m+dl]+=price*0.9/sm;for(let t=0;t<T;t++)L.sell[t]=(L.dep[t]+L.settle[t])*0.03;
  const u=Array.from({length:T},(_,t)=>L.dep[t]+L.settle[t]-L.sell[t]-L.land[t]-L.cons[t]-L.fees[t]-L.cont[t]);
  let used=0,bal=0,peak=0,int=0;const eq=z(),eqIn=z(),draw=z(),intA=z(),rep=z();
  for(let t=0;t<T;t++){const i=bal*rate;bal+=i;int+=i;intA[t]=i;const cf=u[t];if(cf<0){let need=-cf;const e=V.prorata?need*(1-P.ltc):Math.min(need,Math.max(0,P.equity-used));used+=e;need-=e;eqIn[t]=e;bal+=need;draw[t]=need;eq[t]=-e}else{const r=Math.min(bal,cf);bal-=r;rep[t]=r;eq[t]=cf-r}if(bal>peak)peak=bal}if(bal>1)eq[T-1]-=bal;
  const ir=fl=>{const r=irrP(fl);return V.nominal?r*ppy*100:(Math.pow(1+r,ppy)-1)*100};const rev=[...L.dep,...L.settle].reduce((a,b)=>a+b,0),sell=L.sell.reduce((a,b)=>a+b,0),cst=['land','cons','fees','cont'].reduce((s,k)=>s+L[k].reduce((a,b)=>a+b,0),0),tc=cst+int;
  return{L,u,eq,eqIn,draw,intA,rep,T,ppy,lirr:ir(eq),uirr:ir(u),np:rev-sell-tc,tc,rev,peak}}
function write(V,name){const b=build(V),sg=V.neg?-1:1;const hdr=['Line','Total',...Array.from({length:b.T},(_,m)=>{const mm=m*(V.q?3:1),y=2026+Math.floor(mm/12),mo=mm%12;return V.text?['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'][mo]+'-'+String(y).slice(2):Math.round(Date.UTC(y,mo,1)/864e5)+25569})];
  const row=(l,a,s=1)=>[l,a.reduce((x,c)=>x+c,0)*s,...a.map(v=>Math.round(v*s*100)/100)];
  const CF=[['Cash Flow'],[],hdr,['REVENUE'],row('Sales Deposits',b.L.dep),row('Sales Settlements',b.L.settle),['COSTS'],row('Land Purchase Price',b.L.land,sg),row('Construction Costs',b.L.cons,sg),row('Professional Fees',b.L.fees,sg),row('Contingency',b.L.cont,sg),row('Selling Costs (Agents)',b.L.sell,sg),...(V.nonet?[]:[row('Net Cash Flow before Funding',b.u)]),['FUNDING'],row('Equity Contribution',b.eqIn),row('Loan 1 Drawdown',b.draw),row('Loan 1 Interest',b.intA),row('Loan 1 Repayment',b.rep),row('Net Cash Flow to Equity',b.eq)];
  const wb=X.utils.book_new();X.utils.book_append_sheet(wb,X.utils.aoa_to_sheet([['Cash Flow Title','Variant '+name],['Project IRR (ungeared)',b.uirr/100],['Equity IRR (geared)',b.lirr/100],['Net Development Profit',b.np],['Total Development Cost',b.tc],['Gross Sales Revenue',b.rev],['Peak Debt',b.peak]]),'Summary');
  X.utils.book_append_sheet(wb,X.utils.aoa_to_sheet(CF),V.q?'Quarterly CF':'Cash Flow');fs.writeFileSync(__dirname+`/var_${name}.xlsx`,X.write(wb,{type:'buffer',bookType:'xlsx'}));
  const S={price10:{price:-10},cost15:{cost:15},delay6:{delay:6},rate2:{rate:2},combo:{price:-5,cost:10,delay:3}},T={};for(const [k,d] of Object.entries(S)){const r=build(V,d);T[k]={d,lirr:r.lirr,uirr:r.uirr}}return T}
const VARS={quarterly:{q:1},negcosts:{neg:1},prorata:{prorata:1},nonet:{nonet:1},nominal:{nominal:1},textdates:{text:1},allofit:{q:1,neg:1,nonet:1,text:1}};const truth={};
for(const [n,V] of Object.entries(VARS))truth[n]=write(V,n);fs.writeFileSync(__dirname+'/var_truth.json',JSON.stringify(truth));console.log('written',Object.keys(VARS).join(', '));
